import{_ as t,o as a,c as i,a3 as n}from"./chunks/framework.DACwFHq9.js";const p=JSON.parse('{"title":"Media Management","description":"How to manage files, images, PDFs, annotations, and health checks in Notely.","frontmatter":{"title":"Media Management","description":"How to manage files, images, PDFs, annotations, and health checks in Notely.","keywords":"media, assets, images, pdf, workspace health, annotations","category":"Workspace"},"headers":[],"relativePath":"workspace/media.md","filePath":"workspace/media.md","lastUpdated":1791395946000}'),s={name:"workspace/media.md"};function o(r,e,d,l,c,g){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="media" tabindex="-1">Media <a class="header-anchor" href="#media" aria-label="Permalink to &quot;Media&quot;">​</a></h1><p>Notely includes an integrated asset library for linking, viewing, and managing media files inside your notes.</p><h2 id="_1-asset-storage" tabindex="-1">1. Asset Storage <a class="header-anchor" href="#_1-asset-storage" aria-label="Permalink to &quot;1. Asset Storage&quot;">​</a></h2><p>All inserted files (images, PDFs, documents) are stored inside the <code>assets/</code> subfolder in your workspace. Markdown links refer to them relatively:</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">![</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">My Image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">./assets/image.png</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><hr><h2 id="_2-image-tools-annotation" tabindex="-1">2. Image Tools &amp; Annotation <a class="header-anchor" href="#_2-image-tools-annotation" aria-label="Permalink to &quot;2. Image Tools &amp; Annotation&quot;">​</a></h2><p>When viewing a note in Preview mode, hover over an image or right-click to access tools:</p><ul><li><strong>Crop</strong>: Recut and trim the image in-app.</li><li><strong>Annotate</strong>: Draw callout lines, arrows, highlights, and text notes on top of the image.</li><li><strong>Original Restore</strong>: Notely stores a backup of the original asset before your first edit, letting you revert changes later.</li></ul><hr><h2 id="_3-workspace-health-checks" tabindex="-1">3. Workspace Health Checks <a class="header-anchor" href="#_3-workspace-health-checks" aria-label="Permalink to &quot;3. Workspace Health Checks&quot;">​</a></h2><p>Keep your assets tidy using the Media Health Dashboard:</p><ul><li><strong>Unused Media</strong>: Lists media files in <code>assets/</code> not referenced by any note. Offers bulk-deletion.</li><li><strong>Missing Assets</strong>: Displays links in notes pointing to files that do not exist.</li><li><strong>Duplicate Media</strong>: Highlights duplicate file contents to save storage.</li></ul><hr><h2 id="_4-diagrams-media-asset-manager" tabindex="-1">4. Diagrams &amp; Media Asset Manager <a class="header-anchor" href="#_4-diagrams-media-asset-manager" aria-label="Permalink to &quot;4. Diagrams &amp; Media Asset Manager&quot;">​</a></h2><p>Notely provides a dedicated full-screen asset manager under <strong>Workspace &gt; Diagrams &amp; Media</strong> (shortcut: <code>Ctrl+Alt+M</code> or <code>Cmd+Alt+M</code>):</p><ul><li><strong>Multi-View Layout Modes</strong>: Switch between three browsing perspectives using the header view mode toolbar: <ul><li><strong>List / Table View</strong>: High-density table displaying Asset Name, Type Badge, File Size, Reference Status, Extraction Status, and Quick Action buttons.</li><li><strong>Card View</strong>: Visual gallery cards featuring rich thumbnails, file metadata chips, extraction badges, and direct action buttons.</li><li><strong>Icon Grid View</strong>: Compact, icon-centric grid view ideal for quick scanning across large media collections.</li></ul></li><li><strong>Fixed Sidebar &amp; Category Filters</strong>: Left sidebar (260px) with real-time counters for Diagrams, UI Prototypes, Images, PDFs, Videos, Audio, Transcripts, and Documents.</li><li><strong>Physical Disk Scanner &amp; Orphan Detection</strong>: Discovers assets on disk across <code>media/</code>, <code>assets/</code>, and <code>images/</code>. Unreferenced assets are highlighted with the <code>⚠️ Unused / Orphans</code> badge and filter tab.</li><li><strong>Asset Bundles</strong>: Audio and video recordings are organized into bundle folders (<code>media/audio/&lt;id&gt;/</code> and <code>media/video/&lt;id&gt;/</code>) containing the primary recording alongside companion <code>transcript.json</code>.</li><li><strong>Integrated Full-Screen Media Viewer</strong>: Standardized modal viewer with 100% full-width layout, subtitle/transcript side drawer, playback speed controls, and copy/download tools.</li><li><strong>Safe Asset Deletion</strong>: Remove unwanted assets with safety confirmation modals that check note references and warn before removing actively linked files.</li><li><strong>Referenced Notes &amp; Line Jumping</strong>: Inspect reference pills to view note names, line numbers, and markdown context snippets, with 1-click navigation to jump directly to the editor position.</li></ul><hr><h2 id="_5-document-text-extraction-caching" tabindex="-1">5. Document Text Extraction &amp; Caching <a class="header-anchor" href="#_5-document-text-extraction-caching" aria-label="Permalink to &quot;5. Document Text Extraction &amp; Caching&quot;">​</a></h2><p>Notely features an automated, background document extraction and indexing engine for office documents and PDFs:</p><h3 id="supported-formats" tabindex="-1">Supported Formats <a class="header-anchor" href="#supported-formats" aria-label="Permalink to &quot;Supported Formats&quot;">​</a></h3><ul><li><strong>Word Documents (<code>.docx</code>)</strong>: OpenXML parsing extracting headings, paragraphs, bulleted/numbered lists, and tables as standard Markdown.</li><li><strong>Spreadsheets (<code>.xlsx</code>, <code>.xls</code>, <code>.csv</code>)</strong>: SheetJS-powered table extraction preserving multi-sheet workbooks (<code>### Sheet: Name</code>) into GFM Markdown tables.</li><li><strong>Presentations (<code>.pptx</code>)</strong>: Slide-by-slide text hierarchy extraction (<code>### Slide N: Title</code>) including presenter speaker notes.</li><li><strong>PDF Documents (<code>.pdf</code>)</strong>: Spatial line clustering and page-segmented Markdown extraction (<code>### Page N</code>).</li></ul><h3 id="unified-tabbed-preview" tabindex="-1">Unified Tabbed Preview <a class="header-anchor" href="#unified-tabbed-preview" aria-label="Permalink to &quot;Unified Tabbed Preview&quot;">​</a></h3><p>When inspecting or previewing supported documents in the gallery or editor:</p><ul><li><strong><code>[ Preview | Extracted Text ]</code> Switcher</strong>: Seamlessly toggle between native rendering and the extracted text view.</li><li><strong>Formatted Reading View</strong>: Formatted paper sheet view with typography, scrollable tables, reading time estimation, and metadata pills (page count, word count, SHA-256 content hash).</li><li><strong>Markdown Source View</strong>: Synchronized line-numbered raw markdown editor with copy, download, and re-extraction actions.</li><li><strong>In-Document Search</strong>: Instant search bar with occurrence counting and keyword highlights across both reading view and raw source lines.</li><li><strong>Persistent Caching</strong>: Document hashes and extracted text are stored in <code>.notes-app/documents.db</code> and <code>.notes-app/extracted/</code> so subsequent reads are instant without re-parsing.</li></ul>',25)])])}const m=t(s,[["render",o]]);export{p as __pageData,m as default};
